with cleaned as (select id, account_id, txn_type, amount, txn_time, merchant, is_flagged, lower(merchant) as merchant_lower, dayofweek(txn_time) as txn_time_dayofweek, coalesce(merchant, 'NONE') as resolved_merchant from transactions where merchant is distinct from 'Shell' and amount < 3900) select *, row_number() over (partition by txn_type order by txn_time desc, id) as latest_rank from cleaned qualify latest_rank = 1
